import random

def is_triangle(a, b, c):
    return a + b > c and a + c > b and b + c > a

def find_worst_case(n, num_trials=100000):
    max_not_triangles = 0
    best_triangles = []
    for _ in range(num_trials):
        triangles = []
        for _ in range(n):
            a = random.uniform(1, 100)
            b = random.uniform(1, 100)
            c = random.uniform(abs(a-b) + 0.01, a+b - 0.01)
            triangles.append((a, b, c))

        gs = sorted([t[0] for t in triangles], reverse=True)
        ps = sorted([t[1] for t in triangles], reverse=True)
        os = sorted([t[2] for t in triangles], reverse=True)

        not_triangles = 0
        for a in range(n):
            if not is_triangle(gs[a], ps[a], os[a]):
                not_triangles += 1
        if not_triangles > max_not_triangles:
            max_not_triangles = not_triangles
            best_triangles = triangles
    return max_not_triangles, best_triangles

for n in range(1, 6):
    max_nt, best_tri = find_worst_case(n)
    print(f"n={n}, max_not_triangles={max_nt}")
    if best_tri:
        print(f"  Triangles: {best_tri}")

